@spec vm_temper_entry_spec  src=tests/specs/vm_temper_entry_spec.lua  loc=316  cases=10
@exercises tuning (tuning), trackerView (h.vm), editCursor (h.ec), commandManager (h.cmgr)
@surface   tuning.derive, vm:setGridSize, tuning.midiToStep, ec:setPos, vm:editEvent, vm:digitsStrike, ec:pos, ec:row, vm:digitsBackspace, vm:digitsCommit, vm:digitsActive, vm:entrySignAt, vm:noteProjection, cmgr:invoke
@harness   mk{seed.notes}

# Intent
  Wired entry under a temperament: drives the real tv:editEvent path
  (not a re-implementation) so the pitch/octave snapping it performs is
  the production wiring. The octave column edits the temper's period-
  cycle octave, keeping the scale step, and rejects octaves a note
  cannot sit on exactly. See docs/tuning.md for the coordinate model.

# Helpers
  @fn mk(harness, temper)  @ 37-48
  @fn lane1(h)  @ 50-54
  @fn pitchStops(col)  @ 58-65
      -- The pitch part spans two cursor stops (note letter, octave digit);
      -- discover them so the test is independent of cellWidth.
  @fn octaveShown(h, temper)  @ 68-72
      -- The octave the cell shows: the period-index octave plus the octaveStep bump.
  @fn rootedNote(harness)  @ 75-90
      -- Places a note at the cursor and returns a typist for its octave stop.
  @fn narrowNote(harness)  @ 94-105
      -- Places a note under NARROW and returns the harness, its column index and the
      -- pitch part's three stops: the note name, then the octave's tens and units.

# Cases
  @case 'a shift-held digit walks the places of a two-char octave field'  [harness]  @ 109-130
  @case 'the octave gesture declines on the note-name stop'  [harness]  @ 134-140
  @case 'the octave gesture declines on a cell with no note'  [harness]  @ 144-150
  @case 'a plain digit on the tens place zeroes the units below it'  [harness]  @ 154-161
  @case 'the octave column negates in place, and the next digit keeps the sign'  [harness]  @ 165-186
  @case 'minus on octave zero arms the sign before the digit lands'  [harness]  @ 190-210
  @case 'a negated octave the note cannot sit on is a no-op'  [harness]  @ 214-225
  @case 'octave column keeps the scale step and sets the period-cycle octave'  [harness]  @ 229-257
  @case 'octave column rejects an octave the note cannot sit on exactly'  [harness]  @ 261-283
  @case 'pitch nudge keeps a note in the addressable range (refuses past the ceiling)'  [harness]  @ 287-314

